<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
import {api} from './api'
const config=ref<any>({auth_mode:'api_key',base_url:'',model:'',enabled:false,allow_external:false,allow_evidence:false,has_key:false}), key=ref(''), password=ref(''), error=ref(''), notice=ref(''), job=ref<any>(null), busy=ref(false)
const access=ref<any>({}), codex=ref<any>({}), ownerPassword=ref(''), ownerConfirm=ref(''), models=ref<any[]>([]), catalogNote=ref('')
const android=navigator.userAgent.includes('NihaixiaAndroid/')
let timer:ReturnType<typeof setTimeout>|undefined, oauthTimer:ReturnType<typeof setTimeout>|undefined, disposed=false
async function run(fn:()=>Promise<void>){error.value='';notice.value='';busy.value=true;try{await fn()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function load(){const [c,a]=await Promise.all([api.request<any>('/model/config'),api.request('/access/status')]);config.value=c;access.value=a;codex.value=c.codex||{};if(codex.value.login?.status==='pending')scheduleOAuth()}
async function save(){const {auth_mode,base_url,model,enabled,allow_external,allow_evidence}=config.value;await api.put('/model/config',{auth_mode,base_url:auth_mode==='codex'?'':base_url,model,enabled,allow_external,allow_evidence,...(auth_mode==='api_key'&&key.value?{api_key:key.value}:{})});key.value='';await load();notice.value='配置已保存。密钥输入已清空。'}
async function poll(){job.value=await api.request(`/model/jobs/${job.value.id}`);if(['queued','running'].includes(job.value.status))timer=setTimeout(()=>run(poll),1000)}
async function test(){job.value=await api.post('/model/jobs',{purpose:'test'});await poll()}
function scheduleOAuth(){if(oauthTimer)clearTimeout(oauthTimer);if(!disposed)oauthTimer=setTimeout(()=>run(pollOAuth),1500)}
async function pollOAuth(){codex.value=await api.request('/model/codex');if(codex.value.login?.status==='pending')scheduleOAuth();else if(codex.value.login?.status==='completed')notice.value='Codex授权已保存在电脑端。请保存配置后测试连接。'}
async function startLogin(method:'device'|'browser'){await api.post('/model/codex/login',{method});await pollOAuth()}
async function cancelLogin(){await api.post(`/model/codex/login/${codex.value.login.id}/cancel`,{});await pollOAuth()}
async function logoutCodex(){await api.post('/model/codex/logout',{});await pollOAuth();notice.value='已移除本工作台的Codex授权。'}
async function loadModels(){const result=await api.request<any>('/model/codex/models');models.value=result.items;catalogNote.value=result.scope}
async function setupAccess(){if(ownerPassword.value!==ownerConfirm.value)throw Error('两次访问密码不一致');await api.post('/access/setup',{password:ownerPassword.value});ownerPassword.value='';ownerConfirm.value='';await api.session();access.value=await api.request('/access/status');notice.value='访问密码已设置。可运行 start-lan.cmd 启用局域网。'}
async function logout(){await api.post('/access/logout',{});await api.session();window.dispatchEvent(new Event('tcm-logout'))}
async function backup(){if(android)throw Error('请在电脑网页下载备份');if(password.value.length<12)throw Error('备份密码至少 12 字符');const blob=await api.post<Blob>('/backup',{password:password.value});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`tcm-backup-${new Date().toISOString().slice(0,10)}.tcmbak`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);password.value='';notice.value='加密备份下载已发起。'}
onMounted(()=>run(load));onUnmounted(()=>{disposed=true;if(timer)clearTimeout(timer);if(oauthTimer)clearTimeout(oauthTimer)})
</script>
<template><section><div v-if="error" class="error-box" role="alert">{{error}}</div><div v-if="notice" class="notice" role="status">{{notice}}</div><div class="settings-grid"><div class="panel"><h2>模型服务</h2><p class="hint">只在点击发送或测试时请求模型。测试仅发送固定合成文本。</p>
<label>连接方式<select v-model="config.auth_mode" @change="key=''"><option value="api_key">API Key（兼容接口）</option><option value="codex">Codex账号授权</option></select></label>
<template v-if="config.auth_mode==='api_key'"><label>API基址<input v-model="config.base_url" type="url" placeholder="HTTPS 或 HTTP loopback"></label><label>新API密钥（留空保留现有密钥）<input v-model="key" type="password" autocomplete="new-password"></label><p class="hint">{{config.has_key?'已保存密钥':'尚未保存密钥'}}</p></template>
<div v-else class="result-card"><h3>Codex登录</h3><p>{{codex.logged_in?'本工作台已授权':'尚未授权'}}。授权令牌只在电脑端加密保存。</p><div class="button-row"><button :disabled="busy||codex.login?.status==='pending'" @click="run(()=>startLogin('device'))">设备码登录（推荐手机）</button><button v-if="!android" :disabled="busy||codex.login?.status==='pending'" @click="run(()=>startLogin('browser'))">电脑浏览器登录</button></div><p class="hint">设备码在系统浏览器完成；浏览器回调方式请在运行服务的电脑上完成。登录不等于账号有可用额度。</p>
<template v-if="codex.login?.status==='pending'"><p>等待授权完成……</p><p v-if="codex.login.device_code">设备码：<strong class="device-code">{{codex.login.device_code.code}}</strong></p><p v-if="codex.login.auth_url||codex.login.device_code?.url"><a :href="codex.login.auth_url||codex.login.device_code?.url" target="_blank" rel="noopener noreferrer">打开OpenAI授权页面</a></p><button :disabled="busy" @click="run(cancelLogin)">取消本次授权</button></template><p v-if="codex.login?.error" class="warning">{{codex.login.error}}</p><p v-if="codex.credential_error" class="warning">{{codex.credential_error}}</p><button v-if="codex.logged_in" :disabled="busy" @click="run(logoutCodex)">退出Codex授权</button></div>
<label>模型名<input v-model="config.model" list="codex-models" autocomplete="off"><datalist id="codex-models"><option v-for="m in models" :key="m.id" :value="m.id">{{m.name}}</option></datalist></label><template v-if="config.auth_mode==='codex'"><button :disabled="busy" @click="run(loadModels)">查看SDK模型目录</button><p class="hint">{{catalogNote||'模型目录是SDK信息，账号是否可用需实际测试。'}}</p></template>
<label class="check"><input type="checkbox" v-model="config.enabled">启用模型服务</label><label class="check"><input type="checkbox" :checked="config.allow_external && config.allow_evidence" @change="config.allow_external=($event.target as HTMLInputElement).checked;config.allow_evidence=config.allow_external">允许发送必要症状和书证至所选服务</label><div class="button-row"><button class="primary" :disabled="busy" @click="run(save)">保存配置</button><button :disabled="busy" @click="run(test)">测试已保存的配置</button></div><div v-if="job" class="result-card"><strong>连接测试 · {{job.status}}</strong><pre>{{job.text||'暂无输出'}}</pre><p v-if="job.error" class="warning">{{job.error}}</p></div></div>
<div><div class="panel"><h2>工作台访问与多端</h2><p>网页与安卓连接同一台电脑，使用同一书库和问诊记录。电脑需保持运行。</p><form v-if="access.setup_allowed" @submit.prevent="run(setupAccess)"><label>设置访问密码（12至256字符）<input v-model="ownerPassword" type="password" autocomplete="new-password" minlength="12" maxlength="256" required></label><label>再次输入<input v-model="ownerConfirm" type="password" autocomplete="new-password" minlength="12" maxlength="256" required></label><button :disabled="busy">保存访问密码</button></form><template v-else-if="access.configured"><p>访问密码已设置，当前设备已登录。</p><button :disabled="busy" @click="run(logout)">退出当前设备</button></template><p class="hint">在电脑运行 start-lan.cmd 查看HTTPS局域网地址。安卓需安装为本机CA构建的APK；网页需先核对并信任本机CA。详细步骤见项目使用说明。</p></div>
<div class="panel"><h2>加密备份</h2><p>包含数据库和登记原件；模型授权、访问密码和局域网证书需另行配置。</p><p v-if="android" class="hint">请在电脑网页下载备份和大型原件。安卓支持书库原文、页面图像和问诊。</p><template v-else><label>备份密码（至少12字符）<input v-model="password" type="password" autocomplete="new-password"></label><button :disabled="busy||password.length<12" @click="run(backup)">下载加密备份</button></template><p class="hint">请保管密码；恢复目标目录必须为空。</p></div></div></div></section></template>
